#include "nrvk.hpp"
int main(int argc,char**argv){try{if(argc!=4)throw std::runtime_error("create TARGET SPV NEWCACHE");std::string target=argv[1];if(target!="attn"&&target!="vitattn")throw std::runtime_error("target");std::ifstream exists(argv[3]);if(exists.good())throw std::runtime_error("cache exists");nrvk::Context c;c.create();c.load_pipeline_cache(argv[3]);auto b=c.buffer(4096);nrvk::Kernel k;unsigned bindings=target=="attn"?5:3,push=target=="attn"?44:28;std::vector<VkBuffer>v(bindings,b.handle);k.create(c,argv[2],v,push);auto n=c.save_pipeline_cache();printf("PIPELINE_ONLY target=%s gpu=%s driver=%s bindings=%u push=%u cache_bytes=%zu commandbuffers=0 submits=0 dispatches=0\n",target.c_str(),c.gpu_name.c_str(),c.driver_name.c_str(),bindings,push,n);k.destroy();c.destroy(b);c.destroy();return n?0:1;}catch(const std::exception&e){fprintf(stderr,"PIPELINE_ONLY_FAIL %s\n",e.what());return 1;}}
